//B"H

const events = new Map();
const raws = new Map();
const MAX_EVENTS = 1200;
const MAX_RAWS = 700;
let eventCounter = 0;
let rawCounter = 0;

/**
 * Chapter 28: The Worker Became the Hidden Archive.
 *
 * The Awtsmoos lets the visible page hold only keys. The worker stores event
 * bodies and raw scrolls, then returns them only when one gate is opened.
 */
export function storeEvent(event = {}, stableKey = "") {
  const key = stableKey || `wevt-${Date.now().toString(36)}-${eventCounter++}`;
  events.set(key, event);
  trimOldest(events, MAX_EVENTS);
  return key;
}

export function readEvent(key = "") {
  return events.get(String(key || "")) || null;
}

export function storeRaw(value, stableKey = "") {
  const key = stableKey || `wraw-${Date.now().toString(36)}-${rawCounter++}`;
  raws.set(key, safeJson(value));
  trimOldest(raws, MAX_RAWS);
  return key;
}

export function readRaw(key = "") {
  return raws.get(String(key || "")) || "";
}

/**
 * Trims the oldest records so long streams cannot devour the tab.
 *
 * @param {Map<string, *>} map Ordered storage vessel.
 * @param {number} max Maximum retained sparks.
 * @returns {void}
 */
function trimOldest(map, max) {
  while (map.size > max) map.delete(map.keys().next().value);
}

function safeJson(value) {
  try { return JSON.stringify(value, null, 2); }
  catch { return String(value || ""); }
}

